import test from'node:test';import assert from'node:assert/strict';import{flow,earnOpening,source}from './opening-flow.mjs';import{REWARDS,storyReward,finishStory}from '../opening.js';import{World}from '../world.js';import{Battle,encounterEnemies}from '../battle.js?v=5.6.0';import{compileTechnique}from '../mako.js';
test('New Game is a solo civilian with no unearned money, supplies, spells or teammates',()=>{let{w}=flow();assert.equal(w.scene.key,'home');assert.deepEqual(w.state.party,[0]);assert.deepEqual(w.state.recruited,[0]);assert.equal(w.state.gold,0);assert.deepEqual(w.state.cores,[]);assert.deepEqual(w.state.supports,[]);assert.deepEqual(w.state.items,{tonic:0,ether:0,revive:0});assert.ok(w.state.heroes.every(h=>!h.learned&&!h.loadout.length));assert.equal(w.state.story.armor,false);});
test('home cannot be skipped, parcel and small rewards are once only',()=>{let h=flow(),w=h.w;h.use(w.objects().find(o=>o.type==='portal'));assert.equal(w.scene.key,'home');let mara=w.objects().find(o=>o.type==='npc');h.use(mara);h.use(mara);assert.equal(w.state.items.tonic,2);h.use(w.objects().find(o=>o.type==='portal'));let repair=w.objects().find(o=>o.type==='puzzle'&&o.bit===0);h.use(repair);h.choose();h.use(repair);assert.equal(w.state.gold,20);assert.deepEqual(w.state.party,[0]);});
test('first three members and abilities are earned at distinct causal scenes',()=>{let h=earnOpening(),s=h.w.state;assert.deepEqual(s.party,[0,2,1]);assert.deepEqual(s.cores,['earth','mend']);assert.deepEqual(s.supports,['focus']);assert.equal(s.heroes[0].loadout.length,1);assert.equal(s.heroes[2].loadout.length,0);assert.equal(s.heroes[1].loadout[0].core,'mend');assert.ok(s.heroes[1].learned);assert.equal(s.story.armor,false);assert.ok(s.story.journal.some(e=>e.id==='rook'));assert.ok(s.story.journal.some(e=>e.id==='iona'));});
test('yard and battle gates prevent fighting before the basic tools and first pattern',()=>{let h=flow(),w=h.w;w.loadScene(230);h.finish();assert.equal(w.scene.key,'home');let h2=earnOpening(),w2=h2.w;w2.state.recruited=w2.state.recruited.filter(id=>id!==1);w2.state.party=[0,2];let boss=w2.objects().find(o=>o.type==='boss');h2.use(boss);assert.equal(w2.state.mode,'field');assert.equal(w2.currentBattle,null);});
test('authored rewards delay Link until chapter 3 and third socket until chapter 6',()=>{let{w}=earnOpening();storyReward(w,source.campaign.missions[0]);assert.ok(w.state.supports.includes('break'));assert.equal(w.state.story.slots,2);assert.equal(w.state.story.armor,true);assert.equal(w.state.supports.includes('link'),false);storyReward(w,source.campaign.missions[1]);assert.equal(w.state.supports.includes('link'),false);storyReward(w,source.campaign.missions[2]);assert.ok(w.state.supports.includes('link'));assert.equal(w.state.story.slots,2);for(let n=4;n<=11;n++)storyReward(w,source.campaign.missions[n-1]);assert.equal(w.state.story.slots,3);assert.equal(w.state.cores.length,10);assert.equal(w.state.supports.length,12);storyReward(w,source.campaign.missions[14]);assert.equal(w.state.story.armor,false);});
test('solo and earned saves roundtrip while legacy saves retain their full kit',()=>{let h=flow(),save=h.w.save();h.w.restore(save);assert.deepEqual(h.w.state.party,[0]);let legacy=JSON.parse(save);delete legacy.story;legacy.party=[0,1,2];legacy.recruited=[0,1,2];legacy.cores=['earth','mend','flame'];legacy.gold=400;h.w.restore(legacy);assert.equal(h.w.state.gold,400);assert.equal(h.w.state.party.length,3);assert.equal(h.w.scene.objects.some(o=>o.storyEvent),false);});
test('first guardian is winnable with the actually earned early loadouts',()=>{let{w}=earnOpening(),hs=w.activeHeroes;hs.forEach((h,i)=>{h.x=i;h.y=0;});let es=encounterEnemies(1,true);es.forEach(e=>{e.x=4;e.y=0;});let b=new Battle({heroes:hs,enemies:es});for(let i=0;i<10000&&!b.ended;i++){b.advance(.1);for(let h of b.ready){let low=hs.filter(a=>a.hp>0).sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0];if(h.id===1&&low.hp<low.maxHp*.65)b.command(h.id,'tech',low.id,compileTechnique('mend','focus',{character:1}));else if(h.id===0&&h.mp>=7)b.command(h.id,'tech',b.livingEnemies[0]?.id,compileTechnique('earth','focus'));else if(h.id===1)b.command(h.id,'guard',h.id);else b.command(h.id,'attack',b.livingEnemies[0]?.id);}}assert.equal(b.ended,'win');});
test('both endings resolve the recording question and return to the original home',()=>{for(let choice of[0,1]){let h=earnOpening(),w=h.w;finishStory(w);h.choose(choice);assert.equal(w.state.complete,true);assert.equal(w.state.chapter,25);assert.equal(w.scene.key,'home');h.use(w.objects().find(o=>o.type==='npc'));assert.equal(w.state.story.returnedHome,true);assert.ok(w.state.story.journal.some(e=>e.id==='home'));}});
test('recruitment supplies and chapter gear cannot be collected twice',()=>{let h=earnOpening(),w=h.w,npc=w.scene.objects.find(o=>o.storyEvent==='iona'),items={...w.state.items};h.use(npc);assert.deepEqual(w.state.items,items);storyReward(w,source.campaign.missions[0]);let hp=w.state.heroes[0].maxHp;storyReward(w,source.campaign.missions[0]);assert.equal(w.state.heroes[0].maxHp,hp);assert.equal(w.state.story.rewarded.filter(id=>id===1).length,1);});
